    }

    public boolean isCurrentAnimation(String animation) {
        return this.getCurrentAnimation() == this.getAnimationState(animation);
    }

    public void tick() {
        super.tick();
        if (this.spellCooldown > 0) {
            --this.spellCooldown;
        }
        if (this.idleSpellCool > 0) {
            --this.idleSpellCool;
        }
        if (this.cantDo > 0){
            --this.cantDo;
        }
        if (this.level.isClientSide){
            if (this.isAlive()){
                if (this.isSpellCasting()){
                    this.spellCastParticles();
                }
            }
            this.idleAnimationState.animateWhen(!this.walkAnimation.isMoving() && this.isIdleOrNoAnimation(), this.tickCount);
        } else {
            if (!this.isShooting() && !this.isSpellCasting()) {
                this.setAnimationState(0);
            }
        }
    }

